#!/usr/bin/env python3

import os
from databricks.sdk import WorkspaceClient

def main():
    wc = WorkspaceClient()

    # Configuration
    schema_name = os.environ['MLPAB_DATABRICKS_SCHEMA']  # 'workspace.mlpabcddb7b'
    prefix = os.environ['MLPAB_DATABRICKS_PREFIX']  # 'mlpabcddb7b'

    # Split schema into catalog and schema parts
    catalog_name, schema_part = schema_name.split('.')

    print(f"Using catalog: {catalog_name}, schema: {schema_part}")

    # Step 1: Create a model in the model registry that points to our feature table
    print("Creating model in registry...")

    try:
        model = wc.model_registry.create(
            name=f"{catalog_name}.{schema_part}.features7ab995_model",
            description="Feature table for low-latency lookup",
            tags={"type": "feature_table", "version": "1"}
        )
        print(f"Created model: {model.name}")
    except Exception as e:
        print(f"Error creating model: {e}")

    # Step 2: Create a serving endpoint
    print("Creating serving endpoint...")

    try:
        from databricks.sdk.service.serving import ServingEndpoint, ServedEntity

        endpoint = wc.serving_endpoints.create_and_wait(
            name=f"{prefix}_features7ab995",
            config={
                "served_entities": [{
                    "name": "features7ab995",
                    "entity_type": "MODEL",
                    "workload_size": "Small",
                    "scale_to_zero_enabled": True,
                    "min_provisioned_throughput": 0,
                    "max_provisioned_throughput": 1
                }]
            }
        )
        print(f"Created serving endpoint: {endpoint.name}")
    except Exception as e:
        print(f"Error creating serving endpoint: {e}")

    print("Serving endpoint setup complete!")

if __name__ == "__main__":
    main()
